<template>
  <div class="projects-dashboard">
     <div v-if="!dependenciaSeleccionada" class="dependencias-view">
      <div class="header-container">
        <div class="logo-container">
           <div class="titles">
            <h1>GESTIÓN DE PROYECTOS MUNICIPALES</h1>
            <h2>Seleccione una dependencia</h2>
          </div>
        </div>
        <div class="user-info">
          <span class="user-name">Usuario: Admin</span>
          <span class="last-login">Último acceso: {{ new Date().toLocaleDateString() }}</span>
        </div>
      </div>
      
      <div class="dependencias-grid">
        <div 
          v-for="dependencia in dependencias" 
          :key="dependencia.nombre" 
          class="dependencia-card"
          @click="verificarAccesoDependencia(dependencia)"
          :style="{ borderLeft: `5px solid ${getRandomColor()}` }"
        >
          <div class="dependencia-icon">
            <i :class="getIconForDependencia(dependencia.nombre)"></i>
          </div>
          <div class="dependencia-info">
            <h3>{{ dependencia.nombre }}</h3>
            <div class="stats-container">
              <div class="stat-box">
                <span class="stat-number">{{ countProjectsByDependencia(dependencia.nombre) }}</span>
                <span class="stat-label">Proyectos</span>
              </div>
              <div class="stat-box viable">
                <span class="stat-number">{{ countByDependenciaAndStatus(dependencia.nombre, 'Viable') }}</span>
                <span class="stat-label">Viables</span>
              </div>
              <div class="stat-box pendiente">
                <span class="stat-number">{{ countByDependenciaAndStatus(dependencia.nombre, 'pendiente') }}</span>
                <span class="stat-label">Pendientes</span>
              </div>
            </div>
          </div>
          <div class="access-indicator">
            <i class="fas fa-chevron-right"></i>
          </div>
        </div>
      </div>
      
      <div class="footer-actions">
        <button class="view-all-btn" @click="verificarAccesoTodosProyectos">
          <i class="fas fa-list"></i> Ver todos los proyectos
        </button>
        <div class="system-info">
          <span>Sistema de Gestión de Proyectos v1.0</span>
          <span>© 2025 Municipalidad de Malambo</span>
        </div>
      </div>
    </div>
    
    <!-- Vista de tabla de proyectos (se muestra cuando se selecciona una dependencia) -->
    <div v-else class="projects-view">
      <!-- Cabecera del dashboard -->
      <div class="dashboard-header">
        <div class="header-top">
          <button class="back-btn uppercase" @click="volverADependencias">
            <i class="fas fa-arrow-left"></i> VOLVER
          </button>
          <h1>PROYECTOS: {{ dependenciaSeleccionada }}</h1>
          <div class="header-stats">
            <span class="stat-item">TOTAL: {{ filteredProjects.length }}</span>
            <span class="stat-item">VIABLE: {{ countByStatus('Viable') }}</span>
            <span class="stat-item">PENDIENTE: {{ countByStatus('pendiente') }}</span>
          </div>
        </div>
        
        <div class="controls">
          <div class="filter-group">
            <!-- Filtro por DEPENDENCIA (solo visible en vista de todos los proyectos) -->
            <select 
              v-if="dependenciaSeleccionada === 'TODAS LAS DEPENDENCIAS'"
              v-model="dependenciaFilter" 
              @change="applyFilters"
              class="uppercase"
            >
              <option value="all">TODAS LAS DEPENDENCIAS</option>
              <option 
                v-for="dependencia in dependencias" 
                :key="dependencia.nombre" 
                :value="dependencia.nombre"
              >
                {{ dependencia.nombre }}
              </option>
            </select>
            
            <!-- Filtro por ESTADO -->
            <select v-model="statusFilter" @change="applyFilters" class="uppercase">
              <option value="all">TODOS LOS ESTADOS</option>
              <option value="Viable">VIABLE</option>
              <option value="pendiente">PENDIENTE</option>
            </select>
            
            <input 
              type="text" 
              v-model="searchQuery" 
              placeholder="BUSCAR PROYECTOS..." 
              @input="applyFilters"
              class="uppercase"
            >
          </div>
          <button class="refresh-btn uppercase" @click="loadData">
            <i class="fas fa-sync-alt" :class="{ 'fa-spin': loading }"></i> ACTUALIZAR
          </button>
          <button 
            class="report-btn uppercase" 
            @click="generarReporteDependencia"
            :disabled="dependenciaSeleccionada === 'TODAS LAS DEPENDENCIAS'"
          >
            <i class="fas fa-file-alt"></i> REPORTE
          </button>
          <button 
            v-if="dependenciaSeleccionada === 'TODAS LAS DEPENDENCIAS'"
            class="report-btn uppercase" 
            @click="generarReporteGeneral"
          >
            <i class="fas fa-file-alt"></i> REPORTE GENERAL
          </button>
        </div>
      </div>
    
      <!-- Tabla de proyectos -->
      <div class="table-container">
        <table class="projects-table">
          <thead>
            <tr>
              <th class="col-project">NOMBRE DEL PROYECTO</th>
              <th class="col-status">ESTADO</th>
              <th class="col-bpin">BPIN</th>
              <th class="col-dependencia" v-if="dependenciaSeleccionada === 'TODAS LAS DEPENDENCIAS'">DEPENDENCIA</th>
              <th class="col-actions">ACCIONES</th>
            </tr>
          </thead>
          <tbody>
            <tr v-for="(proyecto, index) in paginatedProjects" :key="index">
              <td class="col-project uppercase">
                <span v-if="proyecto.nombreProyecto && proyecto.nombreProyecto.trim() !== ''">
                  {{ proyecto.nombreProyecto }}
                </span>
                <span v-else class="empty-field">N/A</span>
              </td>
              <td class="col-status" :class="getStatusClass(proyecto.estado)">
                {{ formatStatus(proyecto.estado) }}
              </td>
              <td class="col-bpin uppercase">
                <span v-if="proyecto.bpin && proyecto.bpin.trim() !== ''">{{ proyecto.bpin }}</span>
                <span v-else class="empty-field">N/A</span>
              </td>
              <td class="col-dependencia uppercase" v-if="dependenciaSeleccionada === 'TODAS LAS DEPENDENCIAS'">
                {{ proyecto.dependenciaProponente || 'N/A' }}
              </td>
              <td class="col-actions">
                <button class="action-btn view-btn uppercase" @click="verProyecto(proyecto)">
                  <i class="fas fa-eye"></i> VER
                </button>
              </td>
            </tr>
          </tbody>
        </table>
    
        <div v-if="filteredProjects.length === 0" class="empty-state">
          <i class="fas fa-folder-open"></i>
          <p>NO SE ENCONTRARON PROYECTOS CON LOS FILTROS ACTUALES</p>
        </div>
      </div>
    
      <!-- Paginación -->
      <div class="pagination-controls" v-if="filteredProjects.length > itemsPerPage">
        <button @click="prevPage" :disabled="currentPage === 1">
          <i class="fas fa-chevron-left"></i>
        </button>
        <span class="uppercase">PÁGINA {{ currentPage }} DE {{ totalPages }}</span>
        <button @click="nextPage" :disabled="currentPage === totalPages">
          <i class="fas fa-chevron-right"></i>
        </button>
      </div>
    </div>

    <!-- Modal de detalles -->
    <div v-if="showModal" class="modal-overlay" @click.self="closeModal">
      <div class="modal-content">
        <div class="modal-header">
          <h2>DETALLES DEL PROYECTO</h2>
          <button class="close-btn" @click="closeModal">
            <i class="fas fa-times"></i>
          </button>
        </div>
        <div class="modal-body">
          <div class="detail-row">
            <span class="detail-label">NOMBRE:</span>
            <span class="detail-value uppercase">{{ selectedProject.nombreProyecto || 'N/A' }}</span>
          </div>
          <div class="detail-row">
            <span class="detail-label">ESTADO:</span>
            <span class="detail-value uppercase">{{ selectedProject.estado || 'N/A' }}</span>
          </div>
          <div class="detail-row">
            <span class="detail-label">BPIN:</span>
            <span class="detail-value uppercase">{{ selectedProject.bpin || 'N/A' }}</span>
          </div>
          <div class="detail-row">
            <span class="detail-label">SECTOR PDD:</span>
            <span class="detail-value uppercase">{{ selectedProject.sectorPdd || 'N/A' }}</span>
          </div>
          <div class="detail-row">
            <span class="detail-label">DEPENDENCIA PROPONENTE:</span>
            <span class="detail-value uppercase">{{ selectedProject.dependenciaProponente || 'N/A' }}</span>
          </div>
          <div class="detail-row">
            <span class="detail-label">ENTIDAD TERRITORIAL:</span>
            <span class="detail-value uppercase">{{ selectedProject.entidadTerritorial || 'N/A' }}</span>
          </div>
          <div class="detail-row">
            <span class="detail-label">VIGENCIA INICIAL:</span>
            <span class="detail-value uppercase">{{ selectedProject.vigenciaInicial || 'N/A' }}</span>
          </div>
          <div class="detail-row">
            <span class="detail-label">VIGENCIA FINAL:</span>
            <span class="detail-value uppercase">{{ selectedProject.vigenciaFinal || 'N/A' }}</span>
          </div>
          <div class="detail-row">
            <span class="detail-label">PLAZO:</span>
            <span class="detail-value uppercase">{{ selectedProject.plazo || 'N/A' }}</span>
          </div>
          <div class="detail-row">
            <span class="detail-label">CÓDIGO PROGRAMA PRESUPUESTAL:</span>
            <span class="detail-value uppercase">{{ selectedProject.codigoProgramaPresupuestal || 'N/A' }}</span>
          </div>
          <div class="detail-row">
            <span class="detail-label">CÓDIGO PRODUCTO:</span>
            <span class="detail-value uppercase">{{ selectedProject.codigoProducto || 'N/A' }}</span>
          </div>
          <div class="detail-row">
            <span class="detail-label">NOMBRE RESPONSABLE:</span>
            <span class="detail-value uppercase">{{ selectedProject.nombreResponsable || 'N/A' }}</span>
          </div>
          <div class="detail-row">
            <span class="detail-label">CARGO:</span>
            <span class="detail-value uppercase">{{ selectedProject.cargo || 'N/A' }}</span>
          </div>
        </div>
        <div class="modal-footer">
          <button class="modal-btn uppercase" @click="closeModal">CERRAR</button>
          <button 
            v-if="puedeGenerarCertificado(selectedProject)"
            class="modal-btn download-btn uppercase"
            @click="generarCertificadoPDF(selectedProject)"
          >
            <i class="fas fa-file-pdf"></i> DESCARGAR CERTIFICADO
          </button>
        </div>
      </div>
    </div>
  
    <!-- Modal de autenticación para dependencias -->
    <div v-if="showAuthModal" class="modal-overlay" @click.self="closeAuthModal">
      <div class="modal-content auth-modal">
        <div class="modal-header">
          <h2>ACCESO A LA DEPENDENCIA: {{ dependenciaSeleccionadaAuth }}</h2>
          <button class="close-btn" @click="closeAuthModal">
            <i class="fas fa-times"></i>
          </button>
        </div>
        <div class="modal-body">
          <div class="auth-form">
            <label for="claveDependencia">INGRESE LA CLAVE DE ACCESO:</label>
            <input 
              type="password" 
              id="claveDependencia" 
              v-model="claveIngresada"
              placeholder="Clave de acceso"
              class="uppercase"
              @keyup.enter="validarClaveDependencia"
            >
            <p v-if="authError" class="error-message">{{ authError }}</p>
          </div>
        </div>
        <div class="modal-footer">
          <button class="modal-btn" @click="closeAuthModal">CANCELAR</button>
          <button class="modal-btn confirm-btn" @click="validarClaveDependencia">VALIDAR</button>
        </div>
      </div>
    </div>

    <!-- Modal de autenticación para todos los proyectos -->
    <div v-if="showAuthModalTodos" class="modal-overlay" @click.self="closeAuthModalTodos">
      <div class="modal-content auth-modal">
        <div class="modal-header">
          <h2>ACCESO A TODOS LOS PROYECTOS</h2>
          <button class="close-btn" @click="closeAuthModalTodos">
            <i class="fas fa-times"></i>
          </button>
        </div>
        <div class="modal-body">
          <div class="auth-form">
            <label for="claveTodos">INGRESE LA CLAVE PRINCIPAL:</label>
            <input 
              type="password" 
              id="claveTodos" 
              v-model="claveIngresadaTodos"
              placeholder="Clave principal"
              class="uppercase"
              @keyup.enter="validarClaveTodos"
            >
            <p v-if="authErrorTodos" class="error-message">{{ authErrorTodos }}</p>
          </div>
        </div>
        <div class="modal-footer">
          <button class="modal-btn" @click="closeAuthModalTodos">CANCELAR</button>
          <button class="modal-btn confirm-btn" @click="validarClaveTodos">VALIDAR</button>
        </div>
      </div>
    </div>
  
    <!-- Loading overlay -->
    <div v-if="loading" class="loading-overlay">
      <div class="spinner"></div>
      <p>CARGANDO DATOS DESDE GOOGLE SHEETS...</p>
    </div>
  
    <!-- Error message -->
    <div v-if="error" class="error-message">
      <i class="fas fa-exclamation-triangle"></i>
      <span class="uppercase">{{ error }}</span>
      <button class="retry-btn uppercase" @click="loadData">REINTENTAR</button>
    </div>
  </div>
</template>

<script>
import Papa from 'papaparse';
import pdfMake from 'pdfmake/build/pdfmake';
import pdfFonts from 'pdfmake/build/vfs_fonts';

pdfMake.vfs = pdfFonts.pdfMake.vfs;

export default {
  name: 'ProjectsDashboard',
  data() {
    return {
      proyectos: [],
      filteredProjects: [],
      paginatedProjects: [],
      loading: false,
      error: null,
      searchQuery: '',
      statusFilter: 'all',
      dependenciaFilter: 'all', // Nuevo filtro por dependencia
      dependenciaSeleccionada: null,
      currentPage: 1,
      itemsPerPage: 10,
      showModal: false,
      showAuthModal: false,
      showAuthModalTodos: false,
      selectedProject: {},
      dependenciaSeleccionadaAuth: '',
      claveIngresada: '',
      claveIngresadaTodos: '',
      authError: '',
      authErrorTodos: '',
      dependencias: [
        { nombre: 'SECRETARIA DE SALUD', clave: 'SALUD123' },
        { nombre: 'SECRETARIA DE EDUCACION', clave: 'EDUCACION123' },
        { nombre: 'PROGRAMAS SOCIALES', clave: 'SOCIALES123' },
        { nombre: 'SECRETARIA DE HACIENDA', clave: 'HACIENDA123' },
        { nombre: 'SECRETARIA DE GOBIERNO', clave: 'GOBIERNO123' },
        { nombre: 'OFICINA ASESORA DE PLANEACION', clave: 'PLANEACION123' },
        { nombre: 'SECRETARIA DE DESARROLLO ECONOMICO', clave: 'DESARROLLO123' },
        { nombre: 'CULTURA', clave: 'CULTURA123' },
        { nombre: 'INSTITUTO MUNICIPAL DE DEPORTES', clave: 'DEPORTE123' },
        { nombre: 'INFRAESTRUCTURA', clave: 'INFRAESTRUCTURA123' },
        { nombre: 'SECRETARIA DE TRANSITO Y TRANSPORTE', clave: 'TRANSPORTE123' },
        { nombre: 'TIC', clave: 'TIC123' },
        { nombre: 'MINAS Y ENERGIA', clave: 'MINAS123' },
        { nombre: 'AGRICULTURA Y DESARROLLO RURAL', clave: 'AGRICULTURA123' },
        { nombre: 'INCLUSION SOCIAL Y RECONCILIACION', clave: 'INCLUSION123' },         
        { nombre: 'CIENCIA ,TECNOLOGIA E INNOVACION', clave: 'CIENCIA123' }
      ],
      claveUniversal: 'MALAMBO123'
    };
  },
  computed: {
    totalPages() {
      return Math.ceil(this.filteredProjects.length / this.itemsPerPage);
    }
  },
  mounted() {
    this.loadData();
  },
  methods: {
    getRandomColor() {
      const colors = ['#3498db', '#2ecc71', '#e74c3c', '#f39c12', '#9b59b6', '#1abc9c'];
      return colors[Math.floor(Math.random() * colors.length)];
    },
    
    getIconForDependencia(nombre) {
      const icons = {
    'SECRETARIA DE SALUD': 'fas fa-hospital',
    'SECRETARIA DE EDUCACION': 'fas fa-graduation-cap',
    'PROGRAMAS SOCIALES': 'fas fa-hands-helping',
    'SECRETARIA DE HACIENDA': 'fas fa-money-bill-wave',
    'SECRETARIA DE GOBIERNO': 'fas fa-landmark',
    'OFICINA ASESORA DE PLANEACION': 'fas fa-project-diagram',
    'SECRETARIA DE DESARROLLO ECONOMICO': 'fas fa-chart-line',
    'CULTURA': 'fas fa-theater-masks',
    'INSTITUTO MUNICIPAL DE DEPORTES': 'fas fa-running',
    'INFRAESTRUCTURA': 'fas fa-hard-hat',
    'SECRETARIA DE TRANSITO Y TRANSPORTE': 'fas fa-traffic-light',
    'TIC': 'fas fa-laptop-code',
    'MINAS Y ENERGIA': 'fas fa-bolt',
    'AGRICULTURA Y DESARROLLO RURAL': 'fas fa-barn',
    'INCLUSION SOCIAL Y RECONCILIACION': 'fas fa-hands',
    'CIENCIA ,TECNOLOGIA E INNOVACION': 'fas fa-microscope'
      };
      
      for (const [key, icon] of Object.entries(icons)) {
        if (nombre.includes(key)) return icon;
      }
      return 'fas fa-building';
    },
    
    verificarAccesoDependencia(dependencia) {
      this.dependenciaSeleccionadaAuth = dependencia.nombre;
      this.showAuthModal = true;
      this.claveIngresada = '';
      this.authError = '';
    },
    
    validarClaveDependencia() {
      const dependencia = this.dependencias.find(d => d.nombre === this.dependenciaSeleccionadaAuth);
      
      if (this.claveIngresada === dependencia.clave) {
        this.dependenciaSeleccionada = dependencia.nombre;
        this.closeAuthModal();
        this.applyFilters();
      } else {
        this.authError = 'CLAVE INCORRECTA. POR FAVOR INTENTE NUEVAMENTE.';
      }
    },
    
    closeAuthModal() {
      this.showAuthModal = false;
      this.dependenciaSeleccionadaAuth = '';
      this.claveIngresada = '';
      this.authError = '';
    },
    
    verificarAccesoTodosProyectos() {
      this.showAuthModalTodos = true;
      this.claveIngresadaTodos = '';
      this.authErrorTodos = '';
    },
    
    validarClaveTodos() {
      if (this.claveIngresadaTodos === this.claveUniversal) {
        this.dependenciaSeleccionada = 'TODAS LAS DEPENDENCIAS';
        this.closeAuthModalTodos();
        this.applyFilters();
      } else {
        this.authErrorTodos = 'CLAVE INCORRECTA. POR FAVOR INTENTE NUEVAMENTE.';
      }
    },
    
    closeAuthModalTodos() {
      this.showAuthModalTodos = false;
      this.claveIngresadaTodos = '';
      this.authErrorTodos = '';
    },
    
    seleccionarTodasDependencias() {
      this.dependenciaSeleccionada = 'TODAS LAS DEPENDENCIAS';
      this.applyFilters();
    },
    
    volverADependencias() {
      this.dependenciaSeleccionada = null;
      this.searchQuery = '';
      this.statusFilter = 'all';
      this.dependenciaFilter = 'all';
    },
    
    verProyecto(proyecto) {
      this.selectedProject = proyecto;
      this.showModal = true;
    },
    
    countProjectsByDependencia(dependencia) {
      return this.proyectos.filter(proyecto => 
        proyecto.dependenciaProponente && proyecto.dependenciaProponente === dependencia
      ).length;
    },
    
    countByDependenciaAndStatus(dependencia, status) {
      return this.proyectos.filter(proyecto => 
        proyecto.dependenciaProponente && 
        proyecto.dependenciaProponente === dependencia &&
        proyecto.estado && 
        proyecto.estado.toLowerCase().includes(status.toLowerCase())
      ).length;
    },
    
    async loadData() {
      this.loading = true;
      this.error = null;
      
      try {
        const csvUrl = 'https://docs.google.com/spreadsheets/d/e/2PACX-1vT4NLmv0DjEdzTSNr9GC2RMgc80ktw4qaHoN3CboyyMUPCTSsteZAqLoGZDDKEJaPK3HHrgp6B7I5X6/pub?gid=0&single=true&output=csv';
        const response = await fetch(csvUrl);
        const csvData = await response.text();

        Papa.parse(csvData, {
          header: true,
          skipEmptyLines: true,
          complete: (results) => {
            this.proyectos = results.data.map(row => {
              const nombreProyecto = row['PROYECTO'] 
                ? String(row['PROYECTO'])
                    .replace(/<br>/g, ' ')
                    .replace(/\n/g, ' ')
                    .replace(/\s+/g, ' ')
                    .trim()
                : 'N/A';

              return {
                fechaRecibido: row['FECHARECIBIDO']?.toString().trim() || '',
                registroMGA: row['REGRISTOMGA']?.toString().trim() || '',
                nombreProyecto: nombreProyecto,
                estado: (row['ESTADO']?.toString().trim() || '').toLowerCase(),
                bpin: row['BPIN']?.toString().trim() || '',
                asignado: row['ASIGNADO']?.toString().trim() || '',
                fuenteFinanciacion: row['FUENTEDEFINANCIACION']?.toString().trim() || '',
                valor: row['VALOR']?.toString().trim() || '',
                entidadTerritorial: row['ENTIDAD TERRITORIAL']?.toString().trim() || '',
                vigenciaInicial: row['VIGENCIA INICIAL']?.toString().trim() || '',
                vigenciaFinal: row['VIGENCIA FINAL']?.toString().trim() || '',
                plazo: row['PLAZO']?.toString().trim() || '',
                dependenciaProponente: row['DEPENDENCIA PROPONENTE']?.toString().trim() || '',
                planDesarrolloMunicipal: row['PLAN DE DESARROLLO MUNICIPAL']?.toString().trim() || '',
                estrategiaPlanDesarrollo: row['ESTRATEGIA DEL PLAN DE DESARROLLO DISTRITAL O MUNICIPAL']?.toString().trim() || '',
                sectorPdd: row['SECTOR']?.toString().trim() || '',
                programaPdd: row['PROGRAMA DEL PLAN DESARROLLO DISTRITAL O MUNICIPAL']?.toString().trim() || '',
                metaPdd: row['META PLAN DE DESARROLLO']?.toString().trim() || '',
                contribucionMetaPdd: row['CONTRIBUCIÓN DEL PROYECTO A LA META PDD']?.toString().trim() || '',
                codigoProgramaPresupuestal: row['CODIGO PROGRAMA PRESUPUESTAL']?.toString().trim() || '',
                nombrePrograma: row['NOMBRE DEL PROGRAMA']?.toString().trim() || '',
                codigoProducto: row['CODIGO PRODUCTO']?.toString().trim() || '',
                nombreProducto: row['NOMBRE DEL PRODUCTO']?.toString().trim() || '',
                nombreResponsable: row['NOMBRE RESPONSABLE']?.toString().trim() || '',
                cargo: row['CARGO']?.toString().trim() || ''
              };
            });
            
            this.applyFilters();
          },
          error: (error) => {
            throw new Error(`ERROR AL PARSEAR CSV: ${error.message}`);
          }
        });
      } catch (err) {
        console.error('Error loading data:', err);
        this.error = 'ERROR AL CARGAR LOS DATOS. POR FAVOR VERIFIQUE SU CONEXIÓN.';
      } finally {
        this.loading = false;
      }
    },
    
    applyFilters() {
      this.currentPage = 1;
      
      // Filtro principal por dependencia seleccionada
      if (this.dependenciaSeleccionada && this.dependenciaSeleccionada !== 'TODAS LAS DEPENDENCIAS') {
        this.filteredProjects = this.proyectos.filter(proyecto => 
          proyecto.dependenciaProponente && proyecto.dependenciaProponente === this.dependenciaSeleccionada
        );
      } else {
        this.filteredProjects = [...this.proyectos];
      }
      
      // Filtro adicional por dependencia (solo en vista de todos los proyectos)
      if (this.dependenciaSeleccionada === 'TODAS LAS DEPENDENCIAS' && this.dependenciaFilter !== 'all') {
        this.filteredProjects = this.filteredProjects.filter(proyecto => 
          proyecto.dependenciaProponente && proyecto.dependenciaProponente === this.dependenciaFilter
        );
      }
      
      // Filtro por estado
      if (this.statusFilter !== 'all') {
        this.filteredProjects = this.filteredProjects.filter(proyecto => 
          proyecto.estado && proyecto.estado.toLowerCase().includes(this.statusFilter.toLowerCase())
        );
      }
      
      // Filtro por búsqueda
      if (this.searchQuery) {
        const query = this.searchQuery.toLowerCase().trim();
        this.filteredProjects = this.filteredProjects.filter(proyecto =>
          (proyecto.nombreProyecto && proyecto.nombreProyecto.toLowerCase().includes(query)) ||
          (proyecto.bpin && proyecto.bpin.toLowerCase().includes(query)) ||
          (proyecto.dependenciaProponente && proyecto.dependenciaProponente.toLowerCase().includes(query))
        );
      }
      
      this.updatePagination();
    },
    
    updatePagination() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      this.paginatedProjects = this.filteredProjects.slice(start, end);
    },
    
    nextPage() {
      if (this.currentPage < this.totalPages) {
        this.currentPage++;
        this.updatePagination();
      }
    },
    
    prevPage() {
      if (this.currentPage > 1) {
        this.currentPage--;
        this.updatePagination();
      }
    },
    
    closeModal() {
      this.showModal = false;
      this.selectedProject = {};
    },
    
